export class TomlTable {
  constructor() {
    this.map = new Map()
    this.openedByHeader = false
  }

  get(key) {
    return this.map.get(key)
  }

  has(key) {
    return this.map.has(key)
  }

  set(key, value) {
    this.map.set(key, value)
  }

  keys() {
    return Array.from(this.map.keys())
  }
}

export class TomlArrayOfTables {
  constructor() {
    this.items = []
  }
}

export class TomlInt {
  constructor(value) {
    this.value = value
  }
}

export class TomlFloat {
  constructor(value) {
    this.value = value
  }
}
