import { TomlTable, TomlArrayOfTables, TomlInt, TomlFloat } from './values.js'

const NAME_CHAR_RE = /[A-Za-z0-9_-]/
const NUM_RE = /^[+-]?\d+(?:_\d+)*(?:\.\d+(?:_\d+)*)?(?:[eE][+-]?\d+(?:_\d+)*)?$/

function isSpace(ch) {
  return ch === ' ' || ch === '\t'
}

function skipWS(state) {
  while (state.pos < state.line.length && isSpace(state.line[state.pos])) {
    state.pos++
  }
}

function isAtEnd(state) {
  if (state.pos >= state.line.length) return true
  const ch = state.line[state.pos]
  return ch === '#' || ch === ';'
}

function isBareTerminator(ch) {
  return ch === undefined || ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

// ---- names -----------------------------------------------------------

function parseBasicStringRaw(state, lineNo) {
  // state.pos at opening quote
  const line = state.line
  state.pos++
  let result = ''
  for (;;) {
    if (state.pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
    const ch = line[state.pos]
    if (ch === '"') {
      state.pos++
      return result
    }
    if (ch === '\\') {
      state.pos++
      if (state.pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
      const esc = line[state.pos]
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', '0': '\0' }
      if (Object.prototype.hasOwnProperty.call(simple, esc)) {
        result += simple[esc]
        state.pos++
      } else if (esc === 'u') {
        const hex = line.slice(state.pos + 1, state.pos + 5)
        if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
          throw new ParseError(lineNo, 'invalid escape \\u')
        }
        result += String.fromCharCode(parseInt(hex, 16))
        state.pos += 5
      } else {
        throw new ParseError(lineNo, `invalid escape \\${esc}`)
      }
    } else {
      result += ch
      state.pos++
    }
  }
}

function parseLiteralStringRaw(state, lineNo) {
  const line = state.line
  const start = state.pos + 1
  const idx = line.indexOf("'", start)
  if (idx === -1) throw new ParseError(lineNo, 'unterminated string')
  const result = line.slice(start, idx)
  state.pos = idx + 1
  return result
}

function parseName(state, lineNo) {
  const line = state.line
  const ch = line[state.pos]
  if (ch === '"') return parseBasicStringRaw(state, lineNo)
  if (ch === "'") return parseLiteralStringRaw(state, lineNo)
  if (ch !== undefined && NAME_CHAR_RE.test(ch)) {
    const start = state.pos
    while (state.pos < line.length && NAME_CHAR_RE.test(line[state.pos])) state.pos++
    return line.slice(start, state.pos)
  }
  throw new ParseError(lineNo, 'expected a name')
}

function parseDottedName(state, lineNo) {
  const names = []
  skipWS(state)
  names.push(parseName(state, lineNo))
  for (;;) {
    skipWS(state)
    if (state.line[state.pos] === '.') {
      state.pos++
      skipWS(state)
      names.push(parseName(state, lineNo))
    } else {
      break
    }
  }
  return names
}

// ---- values ------------------------------------------------------------

function scanBareToken(state) {
  const line = state.line
  const start = state.pos
  while (state.pos < line.length && !isBareTerminator(line[state.pos])) state.pos++
  return line.slice(start, state.pos)
}

function parseArray(state, lineNo, pathPrefix) {
  state.pos++ // consume '['
  const arr = []
  skipWS(state)
  if (isAtEnd(state)) throw new ParseError(lineNo, 'unterminated array')
  if (state.line[state.pos] === ']') {
    state.pos++
    return arr
  }
  for (;;) {
    const val = parseValue(state, lineNo, pathPrefix)
    arr.push(val)
    skipWS(state)
    if (isAtEnd(state)) throw new ParseError(lineNo, 'unterminated array')
    const ch = state.line[state.pos]
    if (ch === ']') {
      state.pos++
      break
    } else if (ch === ',') {
      state.pos++
      skipWS(state)
      if (isAtEnd(state)) throw new ParseError(lineNo, 'unterminated array')
      if (state.line[state.pos] === ']') {
        state.pos++
        break
      }
      continue
    } else {
      throw new ParseError(lineNo, 'unterminated array')
    }
  }
  return arr
}

function parseInlineTable(state, lineNo, pathPrefix) {
  state.pos++ // consume '{'
  const table = new TomlTable()
  skipWS(state)
  if (isAtEnd(state)) throw new ParseError(lineNo, 'unterminated inline table')
  if (state.line[state.pos] === '}') {
    state.pos++
    return table
  }
  for (;;) {
    skipWS(state)
    const names = parseDottedName(state, lineNo)
    skipWS(state)
    if (isAtEnd(state) || state.line[state.pos] !== '=') {
      throw new ParseError(lineNo, 'expected = in an inline table')
    }
    state.pos++
    skipWS(state)
    const fullPrefix = pathPrefix.concat(names.slice(0, -1))
    const val = parseValue(state, lineNo, pathPrefix.concat(names))
    assignValue(table, names, pathPrefix, val, lineNo)

    skipWS(state)
    if (isAtEnd(state)) throw new ParseError(lineNo, 'unterminated inline table')
    const ch = state.line[state.pos]
    if (ch === '}') {
      state.pos++
      break
    } else if (ch === ',') {
      state.pos++
      skipWS(state)
      if (isAtEnd(state) || state.line[state.pos] === '}') {
        throw new ParseError(lineNo, 'expected a name')
      }
      continue
    } else {
      throw new ParseError(lineNo, 'unterminated inline table')
    }
  }
  return table
}

function parseValue(state, lineNo, pathPrefix) {
  skipWS(state)
  if (isAtEnd(state)) throw new ParseError(lineNo, 'expected a value')
  const ch = state.line[state.pos]
  if (ch === '"') return parseBasicStringRaw(state, lineNo)
  if (ch === "'") return parseLiteralStringRaw(state, lineNo)
  if (ch === '[') return parseArray(state, lineNo, pathPrefix)
  if (ch === '{') return parseInlineTable(state, lineNo, pathPrefix)
  if (ch === ',' || ch === ']' || ch === '}') throw new ParseError(lineNo, 'expected a value')

  const token = scanBareToken(state)
  if (token === 'true') return true
  if (token === 'false') return false
  if (NUM_RE.test(token)) {
    if (token.includes('.') || /[eE]/.test(token)) {
      return new TomlFloat(Number(token.replace(/_/g, '')))
    }
    return new TomlInt(Number(token.replace(/_/g, '')))
  }
  throw new ParseError(lineNo, `invalid value ${token}`)
}

// ---- table walking / assignment ----------------------------------------

function walkIntermediate(table, names, pathPrefix, lineNo) {
  let current = table
  const pathSoFar = pathPrefix.slice()
  for (const name of names) {
    pathSoFar.push(name)
    const existing = current.get(name)
    if (existing === undefined) {
      const nt = new TomlTable()
      current.set(name, nt)
      current = nt
    } else if (existing instanceof TomlTable) {
      current = existing
    } else if (existing instanceof TomlArrayOfTables) {
      current = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${pathSoFar.join('.')} is not a table`)
    }
  }
  return { table: current, path: pathSoFar }
}

function assignValue(table, names, pathPrefix, value, lineNo) {
  const { table: target, path } = walkIntermediate(table, names.slice(0, -1), pathPrefix, lineNo)
  const lastName = names[names.length - 1]
  if (target.has(lastName)) {
    const fullPath = path.concat([lastName]).join('.')
    throw new ParseError(lineNo, `key ${fullPath} is defined twice`)
  }
  target.set(lastName, value)
}

function openTableHeader(table, names, pathPrefix, lineNo) {
  const { table: target, path } = walkIntermediate(table, names.slice(0, -1), pathPrefix, lineNo)
  const lastName = names[names.length - 1]
  const fullPath = path.concat([lastName]).join('.')
  const existing = target.get(lastName)
  if (existing === undefined) {
    const nt = new TomlTable()
    nt.openedByHeader = true
    target.set(lastName, nt)
    return { table: nt, path: path.concat([lastName]) }
  } else if (existing instanceof TomlTable) {
    if (existing.openedByHeader) {
      throw new ParseError(lineNo, `table ${fullPath} is defined twice`)
    }
    existing.openedByHeader = true
    return { table: existing, path: path.concat([lastName]) }
  } else {
    throw new ParseError(lineNo, `${fullPath} is not a table`)
  }
}

function openArrayTableHeader(table, names, pathPrefix, lineNo) {
  const { table: target, path } = walkIntermediate(table, names.slice(0, -1), pathPrefix, lineNo)
  const lastName = names[names.length - 1]
  const fullPath = path.concat([lastName]).join('.')
  const existing = target.get(lastName)
  let aot
  if (existing === undefined) {
    aot = new TomlArrayOfTables()
    target.set(lastName, aot)
  } else if (existing instanceof TomlArrayOfTables) {
    aot = existing
  } else {
    throw new ParseError(lineNo, `${fullPath} is not an array of tables`)
  }
  const nt = new TomlTable()
  aot.items.push(nt)
  return { table: nt, path: path.concat([lastName]) }
}

// ---- header line ---------------------------------------------------------

function parseHeaderLine(state, lineNo) {
  const line = state.line
  let isArray = false
  state.pos++ // consume first '['
  if (line[state.pos] === '[') {
    isArray = true
    state.pos++
  }
  const names = parseDottedName(state, lineNo)
  skipWS(state)
  if (isArray) {
    if (line[state.pos] === ']' && line[state.pos + 1] === ']') {
      state.pos += 2
    } else {
      throw new ParseError(lineNo, 'unterminated table header')
    }
  } else {
    if (line[state.pos] === ']') {
      state.pos += 1
    } else {
      throw new ParseError(lineNo, 'unterminated table header')
    }
  }
  skipWS(state)
  if (!isAtEnd(state)) {
    throw new ParseError(lineNo, 'trailing text after a table header')
  }
  return { names, isArray }
}

// ---- document / driver ---------------------------------------------------

export function parseDocument(text) {
  const root = new TomlTable()
  let current = root
  let currentPath = []

  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const state = { line: raw, pos: 0 }
    skipWS(state)
    if (isAtEnd(state)) continue

    if (state.line[state.pos] === '[') {
      const { names, isArray } = parseHeaderLine(state, lineNo)
      if (isArray) {
        const result = openArrayTableHeader(root, names, [], lineNo)
        current = result.table
        currentPath = result.path
      } else {
        const result = openTableHeader(root, names, [], lineNo)
        current = result.table
        currentPath = result.path
      }
    } else {
      const names = parseDottedName(state, lineNo)
      skipWS(state)
      if (isAtEnd(state) || state.line[state.pos] !== '=') {
        throw new ParseError(lineNo, 'expected key = value')
      }
      state.pos++
      skipWS(state)
      const value = parseValue(state, lineNo, currentPath.concat(names))
      skipWS(state)
      if (!isAtEnd(state)) {
        throw new ParseError(lineNo, 'trailing text after a value')
      }
      assignValue(current, names, currentPath, value, lineNo)
    }
  }

  return root
}
"}

