  const { table: target, path } = walkIntermediate(table, names.slice(0, -1), pathPrefix, lineNo)
  const lastName = names[names.length - 1]
  const fullPath = path.concat([lastName]).join('.')
  const existing = target.get(lastName)
  if (existing === undefined) {
    const nt = new TomlTable()
    nt.openedByHeader = true
    target.set(lastName, nt)
    return { table: nt, path: path.concat([lastName]) }
  } else if (existing instanceof TomlTable) {
    if (existing.openedByHeader) {
      throw new ParseError(lineNo, `table ${fullPath} is defined twice`)
    }
    existing.openedByHeader = true
    return { table: existing, path: path.concat([lastName]) }
  } else {
    throw new ParseError(lineNo, `${fullPath} is not a table`)
  }
