  if (value instanceof TomlTable) {
    const keys = sortedKeys(value)
    if (keys.length === 0) return '{}'
    const lines = keys.map(
      (k) => pad(indentLevel + 1) + JSON.stringify(k) + ': ' + jsonStringify(value.get(k), indentLevel + 1),
    )
    return '{\n' + lines.join(',\n') + '\n' + pad(indentLevel) + '}'
  }
