    const items = value.items
    if (items.length === 0) return '[]'
    const lines = items.map((it) => pad(indentLevel + 1) + jsonStringify(it, indentLevel + 1))
    return '[\n' + lines.join(',\n') + '\n' + pad(indentLevel) + ']'
  }
  if (Array.isArray(value)) {
    if (value.length === 0) return '[]'
    const lines = value.map((v) => pad(indentLevel + 1) + jsonStringify(v, indentLevel + 1))
    return '[\n' + lines.join(',\n') + '\n' + pad(indentLevel) + ']'
  }
  if (value instanceof TomlInt || value instanceof TomlFloat) {
    return JSON.stringify(value.value)
  }
  if (typeof value === 'boolean' || typeof value === 'string') {
    return JSON.stringify(value)
  }
  throw new Error('unknown value type')
}

export function toJSON(root) {
  return jsonStringify(root, 0) + '\n'
}

function walk(node, path, out) {
  if (node instanceof TomlTable) {
    for (const k of sortedKeys(node)) {
      const child = node.get(k)
      const childPath = path === '' ? k : path + '.' + k
      out.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, out)
    }
  } else if (node instanceof TomlArrayOfTables) {
    node.items.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(item)}`)
